import{_ as r,o as e,c as s,a2 as t}from"./chunks/framework.DuPBmefI.js";const u=JSON.parse('{"title":"中华基金中学 · 2026年资料 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"cfss","school_zh":"中华基金中学","school_en":"The Chinese Foundation Secondary School","grade":"s1","year":"2026-source","year_label":"2026年资料","type":"interview","title":"中华基金中学 · 2026年资料 · 中一 · 面试","anonymous":true,"source_ids":["CFSS-S1-2026-GROUP-FAIRNESS","CFSS-S1-2627-OFFICIAL"],"rounds":["r1","unknown","r2"]},"headers":[],"relativePath":"reports/cfss/s1/2026-source-interview.md","filePath":"reports/cfss/s1/2026-source-interview.md"}'),a={name:"reports/cfss/s1/2026-source-interview.md"};function n(p,o,c,i,l,d){return e(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="中华基金中学-·-2026年资料-·-中一-·-面试" tabindex="-1">中华基金中学 · 2026年资料 · 中一 · 面试 <a class="header-anchor" href="#中华基金中学-·-2026年资料-·-中一-·-面试" aria-label="Permalink to &quot;中华基金中学 · 2026年资料 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/cfss">← 返回中华基金中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-cfss-s1-2026-group-fairness" tabindex="-1">资料来源：中华基金中学中一入学信息.pdf <a class="header-anchor" href="#record-cfss-s1-2026-group-fairness" aria-label="Permalink to &quot;资料来源：中华基金中学中一入学信息.pdf {#record-cfss-s1-2026-group-fairness}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 普通话及英语</p><p><strong>个人与小组面试</strong></p><p>包括个人面试与小组面试。家长回忆现场人数较多，约每5至10分钟有一批学生入场；这是分批进场间隔。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>班长处事公平</strong></p><p>小组讨论：如果班长对自己的好朋友特别好，对其他同学却冷落、不公，应该怎样处理？</p><p><strong>个人题目</strong></p><p>个人环节包含阅读理解及成语填空。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>看图讲故事与追问</strong></p><p>小组根据图片讲故事，随后老师分别向每位考生提出一个相关问题。</p></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>难度与流程体验</strong></p><p>考生觉得题目有一定难度；家长认为流程紧凑、内容有挑战。</p></blockquote><h2 id="record-cfss-s1-2627-official" tabindex="-1">资料来源：中华基金中一收生程序.pdf；中华基金S1_admission_FAQ.pdf <a class="header-anchor" href="#record-cfss-s1-2627-official" aria-label="Permalink to &quot;资料来源：中华基金中一收生程序.pdf；中华基金S1_admission_FAQ.pdf {#record-cfss-s1-2627-official}&quot;">​</a></h2><p><strong>资料类型：</strong> 学校官方：2026/27招生安排</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示-1" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示-1" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 中文及英语</p><p><strong>第一轮｜2026年1月3日</strong></p><p>首轮设约4人小组及个人面见。小学四、五年级操行与中英数各科平均须达B+或以上才入围；约面试前一星期电邮通知。须带齐小四、小五全年及小六上学期学生手册和家课日志／手册，作为相关评分依据。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 中文及英语</p><p><strong>第二轮｜2026年1月16日至26日</strong></p><p>合适申请者获邀个人面见。2月26日起分批公布结果，次轮落选者自动列候补，候补期至7月6日。</p></blockquote><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>语言与评分</strong></p><p>中文部分依据报名表家庭常用语言安排粤语或普通话，另有英语。整体收生比重：学业40%、操行20%、活动及服务20%、面试20%。</p><p><strong>改期条件</strong></p><p>个人理由一般不获改期；因学校考试，或代表学校、团体、香港参加全港、全国或世界级比赛／表演，可尽早附官方证明申请，须经学校酌情批准。</p></blockquote>',23)])])}const g=r(a,[["render",n]]);export{u as __pageData,g as default};
